package com.ventas.service;
import com.ventas.dto.SettingsModels.*;
import com.ventas.repository.SettingsRepository;
import com.ventas.security.AuthFailure;
import com.ventas.security.AuthModels.Identity;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.*;import java.util.function.Supplier;
import org.springframework.context.annotation.Profile;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
@Service @Profile("db")
public class SettingsService{
 static final Set<String> GENERAL=Set.of("NEGOCIO.NOMBRE_COMERCIAL","NEGOCIO.RAZON_SOCIAL","NEGOCIO.RUC","NEGOCIO.DIRECCION","NEGOCIO.TELEFONO","VENTAS.IGV_PORC","VENTAS.DESCUENTO_MAX_PORC","VENTAS.BOLETA_DNI_DESDE","VENTAS.PLAZO_CREDITO_DIAS","VENTAS.DEVOLUCION_DIAS","COTIZACION.VIGENCIA_DIAS","SEGURIDAD.SESION_MIN","SEGURIDAD.INTENTOS_MAX","SEGURIDAD.BLOQUEO_MIN");
 static final Set<String> PRINT=Set.of("COMPROBANTE.FORMATO","COMPROBANTE.PIE","COMPROBANTE.TAMANO_TEXTO");
 static final Set<String> READONLY=Set.of("NEGOCIO.MONEDA","SEGURIDAD.ZONA_HORARIA","COMPROBANTE.VERSION_PLANTILLA","COMPROBANTE.MOSTRAR_CODIGO","COMPROBANTE.EMISION_ELECTRONICA");
 private final SettingsRepository repo;private final BusinessTransactions tx;private final TransactionTemplate transaction;private final ObjectMapper mapper;
 public SettingsService(SettingsRepository repo,BusinessTransactions tx,TransactionTemplate transaction,ObjectMapper mapper){this.repo=repo;this.tx=tx;this.transaction=transaction;this.mapper=mapper;}
 private void access(Identity a,String permission){if(a==null||!a.rol().equals("ADM")||a.cambioClaveObligatorio()||!a.permisos().contains(permission))throw new AuthFailure(403,"Solo administración puede acceder a esta configuración");}
 private String permission(boolean printing){return printing?"CFG.TICKET":"CFG.PARAMETROS";}
 private Parameter virtualSize(){return new Parameter("COMPROBANTE.TAMANO_TEXTO","COMPROBANTE","NORMAL","TEXTO",null,null,"Tamaño del texto impreso",true,null);}
 public List<Parameter> parameters(Identity a,boolean printing){access(a,permission(printing));return parameters(printing);}
 private List<Parameter> parameters(boolean printing){Set<String> editable=printing?PRINT:GENERAL;var rows=new ArrayList<Parameter>();for(var p:repo.parameters(printing))if(editable.contains(p.clave())||READONLY.contains(p.clave()))rows.add(new Parameter(p.clave(),p.grupo(),p.valor(),p.tipo(),p.minimo(),p.maximo(),p.descripcion(),editable.contains(p.clave()),p.version()));if(printing&&rows.stream().noneMatch(p->p.clave().equals("COMPROBANTE.TAMANO_TEXTO")))rows.add(virtualSize());return rows;}
 private <T>T mutate(Identity a,String pc,String permission,Supplier<T> operation){access(a,permission);return transaction.execute(s->{repo.serialize();return tx.write(a,pc,permission,()->{if(!repo.admin(a.id()))throw new AuthFailure(403,"Solo administración puede modificar esta configuración");return operation.get();});});}
 private void version(LocalDateTime expected,LocalDateTime current){if(!Objects.equals(expected,current))throw new AuthFailure(409,"La configuración cambió. Actualiza la pantalla antes de guardar");if(current!=null&&expected==null)throw new AuthFailure(400,"Falta la versión del registro");}
 private String json(Object v){if(v==null)return null;try{return mapper.writeValueAsString(v);}catch(Exception e){throw new IllegalStateException("No se pudo preparar la auditoría");}}
 void validate(Parameter p,String v){String k=p.clave();if(v==null||v.length()>300||v.indexOf(0)>=0)throw new AuthFailure(400,"Valor demasiado largo o inválido: "+k);
  if(p.tipo().equals("ENTERO")||p.tipo().equals("DECIMAL")){if(!v.matches(p.tipo().equals("ENTERO")?"-?[0-9]{1,16}":"-?[0-9]{1,16}([.][0-9]{1,6})?"))throw new AuthFailure(400,"Revisa el formato numérico de "+k);BigDecimal n=new BigDecimal(v);if(p.minimo()!=null&&n.compareTo(p.minimo())<0||p.maximo()!=null&&n.compareTo(p.maximo())>0)throw new AuthFailure(400,"Valor fuera de los límites de "+k);}
  if(k.equals("NEGOCIO.NOMBRE_COMERCIAL")&&(v.strip().length()<3||v.length()>150))throw new AuthFailure(400,"El nombre comercial debe tener entre 3 y 150 caracteres");
  if(k.equals("NEGOCIO.RAZON_SOCIAL")&&v.length()>150||k.equals("NEGOCIO.DIRECCION")&&v.length()>200||k.equals("NEGOCIO.TELEFONO")&&v.length()>30)throw new AuthFailure(400,"Revisa la longitud de "+k);
  if(k.equals("NEGOCIO.RUC")&&!v.isEmpty()&&(!v.matches("[0-9]{11}")||v.equals("00000000000")))throw new AuthFailure(400,"El RUC debe tener 11 dígitos distintos de cero o quedar vacío mientras se configura");
  if(k.equals("COMPROBANTE.FORMATO")&&!Set.of("A4","TICKET_80").contains(v))throw new AuthFailure(400,"Selecciona A4 o ticket de 80 mm");
  if(k.equals("COMPROBANTE.TAMANO_TEXTO")&&!Set.of("NORMAL","GRANDE").contains(v))throw new AuthFailure(400,"Selecciona tamaño normal o grande");
 }
 public List<Parameter> save(Identity a,String pc,boolean printing,Changes input){return mutate(a,pc,permission(printing),()->{Set<String> allowed=printing?PRINT:GENERAL;Set<String> seen=new HashSet<>();var changes=new ArrayList<>(input.cambios());changes.sort(Comparator.comparing(Change::clave));for(var c:changes){if(!allowed.contains(c.clave())||!seen.add(c.clave()))throw new AuthFailure(400,"Parámetro no editable o repetido: "+c.clave());var existing=repo.parameter(c.clave(),true);Parameter before=existing.orElseGet(()->{if(c.clave().equals("COMPROBANTE.TAMANO_TEXTO"))return virtualSize();throw new AuthFailure(404,"Parámetro no encontrado");});version(c.version(),before.version());validate(before,c.valor());if(before.valor().equals(c.valor()))continue;if(existing.isEmpty())repo.createTextSize(c.valor());else repo.value(c.clave(),c.valor());Parameter after=repo.parameter(c.clave(),false).orElseThrow();repo.audit(a.id(),printing?"CFG.TICKET":"CFG.PARAMETROS","parametro_sistema",null,json(before),json(after));}return parameters(printing);});}
 public List<Series> series(Identity a){access(a,"CFG.SERIES");return repo.series();}
 private Series series(long id,boolean lock){return repo.series(id,lock).orElseThrow(()->new AuthFailure(404,"Serie no encontrada"));}
 private void type(SeriesInput i){if(i.serie()==null||i.tipo()==null||!i.serie().matches(i.tipo()+"[0-9]{3}")||i.inicial()<1||i.inicial()>2147483646)throw new AuthFailure(400,"La serie debe comenzar con el tipo de documento y tener tres dígitos");}
 public Series create(Identity a,String pc,SeriesInput input){type(input);return mutate(a,pc,"CFG.SERIES",()->{long id=repo.createSeries(input);Series after=series(id,false);repo.audit(a.id(),"CFG.SERIE_CREAR","serie_comprobante",id,null,json(after));return after;});}
 private void remaining(Series before){if(before.estado().equals("A")&&repo.otherActive(before.tipo(),before.id())==0)throw new AuthFailure(409,"Activa otra serie del mismo tipo antes de retirar la última disponible");}
 public Series update(Identity a,String pc,long id,SeriesInput input){type(input);return mutate(a,pc,"CFG.SERIES",()->{Series before=series(id,true);if(input.version()==null)throw new AuthFailure(400,"Falta la versión de la serie");version(input.version(),before.version());if(before.usada())throw new AuthFailure(409,"Una serie utilizada conserva su tipo, código y numeración inicial");if(input.inicial()<before.inicial())throw new AuthFailure(409,"El correlativo inicial no puede retroceder");if(!before.tipo().equals(input.tipo()))remaining(before);repo.editSeries(id,input);Series after=series(id,false);repo.audit(a.id(),"CFG.SERIE_EDITAR","serie_comprobante",id,json(before),json(after));return after;});}
 public Series state(Identity a,String pc,long id,State input){return mutate(a,pc,"CFG.SERIES",()->{Series before=series(id,true);version(input.version(),before.version());if(before.estado().equals(input.estado()))return before;if(input.estado().equals("I"))remaining(before);repo.state(id,input.estado());Series after=series(id,false);repo.audit(a.id(),"CFG.SERIE_ESTADO","serie_comprobante",id,json(before),json(after));return after;});}
 public Label label(Identity a,String pc,LabelRequest input){return mutate(a,pc,"CFG.ETIQUETAS",()->{Label result=repo.label(input).orElseThrow(()->new AuthFailure(409,"Selecciona una presentación activa y un código registrado; el código interno solo identifica la presentación base"));if(!Set.of("EAN13","CODE128").contains(result.simbologia()))throw new AuthFailure(400,"Simbología no compatible");if(result.simbologia().equals("CODE128")&&!result.codigo().matches("[ -~]{1,80}"))throw new AuthFailure(400,"El código no se puede representar en Code 128");repo.audit(a.id(),"CFG.ETIQUETAS","presentacion_producto",input.presentacionId(),null,json(result));return result;});}
}
